-- public.errand_fetch_n(p_world uuid, c creature)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.errand_fetch_n(p_world uuid, c creature)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_kind text; dd deed; v_job record; v_h placed; n int := stage_loads(c);
begin
  if n <= 1 then return 1; end if;
  v_kind := coalesce(c.job, (select sd.gathers from species_def sd where sd.id = c.species));
  select * into dd from my_deed(p_world, c.keeper) md where md.world_id is not null;
  if v_kind = 'hod' then
    select * into v_job from hod_needing_stocked(p_world, c.keeper, dd.x, dd.y, work_range(c));
    if v_job.item is null then return 1; end if;
    return greatest(1, least(n, hod_left(p_world, v_job.kind, v_job.level, v_job.dir, v_job.x, v_job.y, v_job.ref, v_job.n, v_job.item)));
  elsif v_kind = 'stoke' then
    v_h := stoke_hearth(p_world, c, c.fetching, dd.x, dd.y, work_range(c));
    if v_h.id is null or coalesce(fuel_value(c.fetching), 0) <= 0 then return 1; end if;
    return greatest(1, least(n, floor((stoke_room(v_h) - placed_fuel(v_h)) / fuel_value(c.fetching))::int));
  end if;
  return n;
end $function$
